1/jour - &lt;a class=&quot;pagelink&quot; href=&quot;Convocation-(Capacit&#233;).html&quot; title=&quot;Convocation (Mag)&quot;&gt;convocation&lt;/a&gt; (niveau 3, 1 &lt;a class=&quot;pagelink&quot; href=&quot;Sepsida&#233;mon.html&quot; title=&quot;Da&#233;mon, Sepsida&#233;mon&quot;&gt;sepsida&#233;mon&lt;/a&gt; 40%)
&lt;/div&gt;
